import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Compression Algorithms for Idealized Systems","description":"","frontmatter":{"translationSource":{"title":"针对理想系统的压缩算法","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}]]},"headers":[],"relativePath":"compression-algorithms-for-implementing-idealized-systems.md","filePath":"logistics/src/page-ZllGoCkftlEvd5lMExXrO2.md"}'),o={name:"compression-algorithms-for-implementing-idealized-systems.md"};function r(n,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><h1 id="compression-algorithms-for-idealized-systems" tabindex="-1">Compression Algorithms for Idealized Systems <a class="header-anchor" href="#compression-algorithms-for-idealized-systems" aria-label="Permalink to &quot;Compression Algorithms for Idealized Systems&quot;">​</a></h1><blockquote><p>Source page ID: <code>ZllGoCkftlEvd5lMExXrO2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><blockquote><p>Building lines with the human brain means using heuristic algorithms.</p><p>—恒星泰斗</p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-54076b3e7fa770ef.gif" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="14pcS9WHvs8xfrSPSKnc53"><p><s>Opening image</s></p></div><p><span id="source-block-wW6QHfP1USjLEMladjHekj"></span></p><h3 id="how-do-humans-lay-out-a-line" tabindex="-1">How Do Humans Lay Out a Line? <a class="header-anchor" href="#how-do-humans-lay-out-a-line" aria-label="Permalink to &quot;How Do Humans Lay Out a Line?&quot;">​</a></h3><p><span id="source-block-uaL3SZXJvWRi8tCAOsKjg9"></span></p><h4 id="taking-325-799-as-an-example" tabindex="-1">Taking 325/799 as an Example <a class="header-anchor" href="#taking-325-799-as-an-example" aria-label="Permalink to &quot;Taking 325/799 as an Example&quot;">​</a></h4><p><span id="source-block-kFyTivAiZwVCBBDDmZ3OQJ"></span></p><h5 id="draft" tabindex="-1">Draft <a class="header-anchor" href="#draft" aria-label="Permalink to &quot;Draft&quot;">​</a></h5><p>Without further ado, let us start with the TopoFlow graph. At the outset we usually get a messy graph:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b26da58bb5f04a11.q90-d24c93e9df94f8ff.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="DdSBxHf2fCU3iPzs7yPfuW"><p>!? 325/799?!</p></div><p>In the first step we tidy up the graph so that its planarization “looks” relatively easy, for example like this:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e959ae217340ca1.q90-a0b813a9e8f78bb0.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="TMveqqiN4IZUgY7ToSXerV"><p>325/799 after tidying</p></div><p>We can call such a rough layout a Draft. Looking at this Draft, we can see several features:</p><p>The next step is to lay it out in the actual game according to the Draft.</p><p><span id="source-block-56Px6IMF9G9gnl3BSVCKDq"></span></p><h5 id="round-1" tabindex="-1">Round 1 <a class="header-anchor" href="#round-1" aria-label="Permalink to &quot;Round 1&quot;">​</a></h5><p>First, place the source and sink, as well as the components that connect directly to the source and sink:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-edd6d4d22e064b37.q90-b132f874ac08915f.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="LqSjfxUrd0bWsxr2XDA6Zf"><p>step 1</p></div><p>Then consider the placement of the main chain:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c0e58cf38e27983c.q90-4a899754e9a1e6bd.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="SRq5GAHG4AiG9p8Zu6BuU8"><p>step 2</p></div><p>To make layout easier, we split apart the three-way merge on the lower side (the flow was verified to remain unchanged), giving:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ff889173e26b66d9.q90-7346467662fc572b.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="76ar2gsl1y8wNqCRPleDBG"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2c152ddcb9542bce.q90-f110626c65a3809a.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="jwCzlI8G1gycgxqNyT2l6w"><p>step 3.2</p></div><p>We continue splitting the lower three-way merge:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f8db3e6ea188340.q90-f06a7a4e0ca9099b.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="3xEMQlKU5Y2tTygkPi5IO5"><p>step 4.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6694e35523aed094.q90-a4ae0147fd549257.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="ciPPIHvGx6qDWHfEi6vgSN"><p>step 4.2</p></div><p>An important observation here: a component&#39;s orientation can be changed dynamically while connecting belts—that is, a component should not have an “orientation” attribute to begin with</p><p>Then lay out the upper-side merging unit:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-aa304f3647f6ffeb.q90-1ccbf4ed31c566d7.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="qhJmout6Jgi8W97nJ219cz"><p>step 5</p></div><p>Continue laying out:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-81adb66e7f074d5d.q90-c1bea0c1892e2940.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="0VekmVzjrBjDbEUYn7Q07n"><p>step 6.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-796819c117d7fa9d.q90-1162a83edb598462.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="yurtIy4ealBxnxe0TNL6vQ"><p>step 6.2</p></div><p>At this point we found that the connection from the lower-left converger → upper-right converger could no longer be established, so we modified the layout:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-74af56a032e69980.q90-fa8dda4de129366c.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="hyBjG3YMQ4G9hwKyRMZFCB"><p>step 7.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-314f4c058d985449.q90-e2cc2b697ef3dc45.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="HZfOj6mEyi8gk6KGkS04bY"><p>step 7.2</p></div><p>Then complete the final connections:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55b86b0962b61116.q90-b6dfae1c76fd940b.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="lkguqyYn4PjZQedkl0fpeg"><p>step 8</p></div><p>So we obtained the first feasible layout (area 110, 34 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-trnc79pKkAzcvat5lLwPk4"></span></p><h5 id="round-2" tabindex="-1">Round 2 <a class="header-anchor" href="#round-2" aria-label="Permalink to &quot;Round 2&quot;">​</a></h5><p>Obviously the result of the first round looks ugly, so we consider rolling back and re-laying out the upper side:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5cb8abd6b0d33c7c.q90-dddecc18c51812c9.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="gCtHP9Ii5zAjWJXjxXtlTR"><p>step 1</p></div><p>Continue:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0b51f713ecc097dc.q90-62ca9a3c91276ecd.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="M3yqNmUq37TqEWB8T4JoLB"><p>step 2</p></div><p>Space on the upper side is tight, so we consider modifying the graph:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3348f44656e3e6fa.q90-8c8c073131fb0eba.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="VfRaDArr8CfUVcoNSNo4Xe"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abc81101899179b5.q90-df3c35e0a6263165.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="MTzRT8j69JFR2h3PxUkJSc"><p>step 3.2</p></div><p>Continue:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8caea85c91e316b2.q90-f210f728f3bd2b07.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="5F9xN7hbpeMQOW823RLI7s"><p>step 4</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-04e7961f2ab79336.q90-11fcc3a56c338ac4.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="I29O44Z0BA0H8ErrNDqLN6"><p>step 5</p></div><p>The second feasible layout (area 99, 31 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-W3WqdXD4YJV2s5YwNQy4Rv"></span></p><h5 id="round-3" tabindex="-1">Round 3 <a class="header-anchor" href="#round-3" aria-label="Permalink to &quot;Round 3&quot;">​</a></h5><p>Roll back the upper side:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cbdbdfe32553503b.q90-13dc059be757a0c9.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="Ke1GSBELTSu8dhMHKBWVcp"><p>step 1</p></div><p>Split the converger:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3ee61b72412b1958.q90-3720e4914eadfcc7.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="3dLtm8HZ35Edwsmuvr0BHZ"><p>step 2.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84f3a8a6d9213725.q90-85761b021248f088.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="NfQKc3CrCMXzXRE1N1KATU"><p>step 2.2</p></div><p>Finally, polish it a little:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ef9d7525a6a8eae2.q90-35025034d085d9b2.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="AWb554q2yv7aMNachZbUlZ"><p>step 3</p></div><p>This gives a fairly decent overall layout (area 88, 32 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-oBffoBBBm5SHKIwM8ww0k2"></span></p><h4 id="what-operations-did-we-perform-along-the-way" tabindex="-1">What Operations Did We Perform Along the Way? <a class="header-anchor" href="#what-operations-did-we-perform-along-the-way" aria-label="Permalink to &quot;What Operations Did We Perform Along the Way?&quot;">​</a></h4><p>First, through “intuition” and “experience” we designed a Draft that “looks good”;</p><p>Second, we essentially used only the following three operations (of course, there were also some local fixes and rollbacks)</p><p>Notice that almost every operation builds on the result of the previous one. The whole layout process grows like a tree (perhaps this also explains why random/genetic algorithms are less efficient: our pruning is much more aggressive).</p><p><span class="mark-red"><s>Only after writing this did I notice that the In box in the 325-799 layout above had accidentally connected to another Converger… but I really don&#39;t want to draw it all again 😡😡😡</s></span></p><p><span id="source-block-VEcokFaAbFbe38SaF0xp8M"></span></p><h3 id="translating-these-processes-into-a-search-strategy-that-guides-heuristic-search" tabindex="-1">Translating These Processes into a Search Strategy That Guides Heuristic Search <a class="header-anchor" href="#translating-these-processes-into-a-search-strategy-that-guides-heuristic-search" aria-label="Permalink to &quot;Translating These Processes into a Search Strategy That Guides Heuristic Search&quot;">​</a></h3><p>Building a global searcher that decides all layout variables at once runs into three problems: the state space is too large, failure feedback arrives too late, and retries discard constraints already satisfied. The question can instead be phrased as: how can layout construction be split into decisions that allow local rollback?</p><p>The decision order is structure selection, coordinate assignment, then port and route assignment. Each step produces a partial state; on failure, roll back to the nearest stable state. In algorithmic terms, these correspond to four components: Draft, PartialState, feedback and compaction.</p><p>The objective is to minimize (Area, N_logic + N_X), where N_logic is the number of logical nodes and N_X the number of crossing units. Candidates must also satisfy geometry, routing and flow constraints. Search operates over partial states rather than directly over complete layouts.</p><p><span id="source-block-MmG8052WMwPMW5Yplp6t9M"></span></p><h4 id="draft-structural-prior" tabindex="-1">Draft: Structural Prior <a class="header-anchor" href="#draft-structural-prior" aria-label="Permalink to &quot;Draft: Structural Prior&quot;">​</a></h4><p>Determine the structure before the coordinates: which chain forms the spine, how Convergers are split between its two sides, and which end the source/sink core lies near. This structural template is the Draft.</p><p>A Draft is a compact structural template derived from the graph using topological sorting. It specifies the spine, recirculation groups, source/sink core and terminal directions, but is not a coordinate solution. Only after the structure is determined can subsequent coordinate search be restricted to sensible regions.</p><p>The figures show five Drafts generated by the algorithm for 325/799:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fc1fb4635c2932b8.q90-baa89aa2b6e7aaef.webp" alt="Compression Algorithms for Idealized Systems"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-42f1e74806485acc.q90-8a2407e46b4b295b.webp" alt="Compression Algorithms for Idealized Systems"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-de86e22d181d8964.q90-9be43bb16ce9abe3.webp" alt="Compression Algorithms for Idealized Systems"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9880e830f5ffc2e9.q90-28e101b1f4222063.webp" alt="Compression Algorithms for Idealized Systems"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9c6f3cd7792d5468.q90-688e4edc08d7abcf.webp" alt="Compression Algorithms for Idealized Systems"></p><p><span id="source-block-UHhN3yCWhGQZnmKs7bZoXc"></span></p><h5 id="main-axis-discovery" tabindex="-1">Main Axis Discovery <a class="header-anchor" href="#main-axis-discovery" aria-label="Permalink to &quot;Main Axis Discovery&quot;">​</a></h5><p>There are two ways to generate a spine:</p><p>The first follows Splitter chains; the second uses direct contact between facilities to join compatible nodes into a contact chain. Both produce an ordered node sequence that serves as the skeleton for subsequent placement.</p><p><span id="source-block-LVCOtpX0WM7SPnUmQA3Jqa"></span></p><h5 id="recirculation-allocation" tabindex="-1">Recirculation Allocation <a class="header-anchor" href="#recirculation-allocation" aria-label="Permalink to &quot;Recirculation Allocation&quot;">​</a></h5><p>Once the spine is fixed, recirculation Convergers must be assigned to its two sides.</p><p>Too little spacing increases conflicts between return paths; too much enlarges the bounding box. First group non-spine Convergers by connectivity, then assign whole groups to the upper or lower bank. This preserves connectivity within return chains and reduces detours between regions.</p><p>Side assignment must also eliminate mirror symmetry: flipping every group to the other side gives the same layout&#39;s mirror image and should not be searched again. The implementation fixes the first group&#39;s side and enumerates only the others. Small graphs use direct enumeration; large graphs use a deterministic balanced-prefix Beam.</p><p>Assignments are ranked by structural measures: inter-bank edge count, peak bank-lane load, attachment span from facilities to the spine, estimated crossings and an area lower bound. Candidates with the longest spine are retained so that short-spine candidates do not occupy the Beam too early.</p><p><span id="source-block-edrIa9oQcN40ZgwjXCoHSH"></span></p><h5 id="source-and-sink-anchors" tabindex="-1">Source and Sink Anchors <a class="header-anchor" href="#source-and-sink-anchors" aria-label="Permalink to &quot;Source and Sink Anchors&quot;">​</a></h5><p>Early construction usually fixes terminals and the facilities directly connected to them first. Terminals sit one grid cell outside the bounding box, with constrained positions, orientations and ports. Once they are fixed, internal facilities have stable coordinate references.</p><p>Accordingly, the algorithm first finds the source anchor and sink anchor, gathers facilities directly connected to terminals into the core, and generates a Draft around it. Fix terminals too late, after internal facilities have spread out, and restoring the constraints is expensive; fix them too early or without a sound basis, and the spine&#39;s position becomes unnecessarily restricted.</p><p><span id="source-block-Ehv613wB81TvuUWAktdsiH"></span></p><h5 id="materializing-the-template" tabindex="-1">Materializing the Template <a class="header-anchor" href="#materializing-the-template" aria-label="Permalink to &quot;Materializing the Template&quot;">​</a></h5><p>A Draft describes relative relationships, not coordinates. Before search, spine, upper, lower and core must be converted into a collision-free unit-grid template:</p><p>The template is only an initial candidate, not a feasible layout. It guarantees neither sufficient ports nor reachable routes; its role is to restrict search to structurally promising compact regions.</p><p><span id="source-block-f8NzRY3rVhZD3JnVumHRkW"></span></p><h5 id="multiple-drafts" tabindex="-1">Multiple Drafts <a class="header-anchor" href="#multiple-drafts" aria-label="Permalink to &quot;Multiple Drafts&quot;">​</a></h5><p>The same graph may have several reasonable structures: the spine may follow a Splitter chain or a contact chain; return paths may lie above or below it; and the source/sink core may lie near one end or span both.</p><p>The algorithm therefore generates a candidate set rather than a single Draft: ordinary Splitter spines, contact-chain spines, paired cores, compressed banks, return lanes, folded/staircase variants, and a few graphs with rewritten topology.</p><p>Actual construction often requires comparing several structural versions: validate the spine, adjust return paths, and finally decide whether to split three-way Convergers. The algorithm turns these versions into parallel candidates instead of retrying them serially.</p><p><span id="source-block-AwzuYNMq8zZh2tpzckyHsT"></span></p><h4 id="partial-states-incremental-construction-and-local-rollback" tabindex="-1">Partial States: Incremental Construction and Local Rollback <a class="header-anchor" href="#partial-states-incremental-construction-and-local-rollback" aria-label="Permalink to &quot;Partial States: Incremental Construction and Local Rollback&quot;">​</a></h4><p>Deciding all coordinates at once is impractical. Placement and routing must advance in turn, rolling back to the nearest stable state on failure. The search state must therefore be a partial layout recording “how far construction has progressed,” rather than a complete layout.</p><p>This is PartialState: it records placed facilities, orientations, routed paths, deferred edges and the latest failure. Each search node is a partial state. Child states are built in independent RouteWorld instances, so failure does not contaminate the parent.</p><p><span id="source-block-a9eTtnUbxXLShN9HpGGmGT"></span></p><h5 id="placement-expand-by-contact-chains" tabindex="-1">Placement: Expand by Contact Chains <a class="header-anchor" href="#placement-expand-by-contact-chains" aria-label="Permalink to &quot;Placement: Expand by Contact Chains&quot;">​</a></h5><p>Expanding one facility at a time invites short-sighted decisions: a coordinate may work now while consuming ports and corridors needed later.</p><p>A more effective expansion unit is a contact chain. Macro / chain expansion places a whole chain at once and tries shorter prefixes on failure. If the entire chain cannot be placed, rollback stays local to that chain instead of resetting the whole layout.</p><p><span id="source-block-7ZaL35XKI91MHQuHF4k7aP"></span></p><h5 id="ranking-completion-first" tabindex="-1">Ranking: Completion First <a class="header-anchor" href="#ranking-completion-first" aria-label="Permalink to &quot;Ranking: Completion First&quot;">​</a></h5><p>Beam ranking uses a completion heuristic: prefer fewer unplaced facilities, more connected edges, a smaller current bounding box, adequate S→C spacing, and facilities closer to the Draft template.</p><p>It expands states nearer completion first instead of exploring all possibilities uniformly.</p><p><span id="source-block-LcU7KvQYp1lssvqBuwN1Ng"></span></p><h5 id="late-orientation" tabindex="-1">Late Orientation <a class="header-anchor" href="#late-orientation" aria-label="Permalink to &quot;Late Orientation&quot;">​</a></h5><p>Section 1 identified a key constraint: facilities should not have their orientation fixed initially; later routes&#39; port requirements should determine it.</p><p>Late orientation implements this: only the root&#39;s initial direction is fixed. Later facilities remain unlocked until routing determines their ports. Early orientation choices therefore do not force later routes to take detours.</p><p>Preserve structural possibilities first, then progressively fix geometric relationships. This order runs through the whole pipeline.</p><p><span id="source-block-gyrOE6wv51aDv3EotxrH1E"></span></p><h4 id="shared-frontier-a-global-queue-and-state-deduplication" tabindex="-1">Shared Frontier: A Global Queue and State Deduplication <a class="header-anchor" href="#shared-frontier-a-global-queue-and-state-deduplication" aria-label="Permalink to &quot;Shared Frontier: A Global Queue and State Deduplication&quot;">​</a></h4><p>Expanding one branch only advances a single search subtree. A graph has multiple structural options, and one Draft is not necessarily optimal.</p><p>If 16 workers each start from scratch, they repeat the same states and the same failures. A shared priority queue lets any worker continue a partial state left by another. States are deduplicated with translation-normalized keys, while different Drafts, topologies and feedback sources use distinct context identifiers.</p><p>The 16 workers share one frontier rather than restarting independently. At most 4 Draft groups are active, with at most 2 expansions in flight per group. Another 4 workers run compaction, while up to 4 auxiliary tasks prepare new Drafts or topology variants. Stalled groups are suspended, not deleted, and can resume when other groups release slots.</p><p>Random restarts and genetic algorithms introduce diversity at the complete-solution level: generate whole individuals, then select. Here diversity operates at the partial-state level: different Drafts form different subtrees, and Beam can prune partial states. A chain that cannot be placed can be rejected before the whole graph is complete. Earlier pruning wastes less work.</p><p><span id="source-block-kZW4tVuVT1wE5GwPr5Yfwt"></span></p><h4 id="feedback-reopening-local-regions-based-on-failure-diagnosis" tabindex="-1">Feedback: Reopening Local Regions Based on Failure Diagnosis <a class="header-anchor" href="#feedback-reopening-local-regions-based-on-failure-diagnosis" aria-label="Permalink to &quot;Feedback: Reopening Local Regions Based on Failure Diagnosis&quot;">​</a></h4><p>A setback should not reset every decision. It is better to roll back to the nearest stable state and reopen only the upper structure or a single Converger.</p><p>Feedback implements this mechanism. Starting from a validated layout, keep most facility positions, orientations and routed paths, and reopen only local regions identified by diagnosis or worth revisiting structurally:</p><p>Feedback seeds come from failure diagnosis and contact relationships in the current layout: failed edges, blocking edges, occupied cells, adjacent machines, and empty rows/columns. The algorithm reopens only the local regions this evidence identifies, rather than randomizing the whole layout again.</p><p>By default, feedback prefers mature, compacted layouts: a Beam solution receives one round of compaction, and that result starts the next feedback round. Only if compaction brings no improvement does it fall back to the original validated layout. Feedback is also limited by generation, family and source so that one local problem cannot consume the whole budget.</p><p><span id="source-block-YvGjYKCxE8z4lwQeGfSZNT"></span></p><h4 id="hardcore-compaction-definitely" tabindex="-1">Hardcore Compaction (Definitely) <a class="header-anchor" href="#hardcore-compaction-definitely" aria-label="Permalink to &quot;Hardcore Compaction (Definitely)&quot;">​</a></h4><blockquote><p>Imagine tofu blocks stuck on a grid, linked by soft conveyor belts<br> Then a force pulls them toward the center<br> Then a little shake shake<br> And the module gets smaller<br> 😆</p><p>— 曜</p></blockquote><p>Once the first feasible layout has been generated, there is usually still room to reduce its area. Section 1&#39;s three iterations reduced the area from 110 to 99 and then 88 by rolling back, splitting/merging and reconnecting an existing layout.</p><p>The algorithm has construction and compaction stages. Construction seeks a gate-valid layout quickly, without pursuing minimum area. Compaction improves only valid layouts locally: the continuous compactor treats machines and belt bends as movable anchors, tightens the layout by physical relaxation, projects it back onto the integer grid, and reroutes with A*.</p><p>Why not compact during construction? The area of an invalid layout is meaningless. A layout may be tighter but lack ports, contain illegal crossings, or have mismatched terminal flow; a smaller objective value does not make it feasible. First construct a valid layout, then compact within the feasible region.</p><p>Compaction moves machines and may create or destroy capacity-0 direct-contact connections. The complete physical-graph gate must therefore run again after compaction.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2ce491e7123ed178.gif" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="X12Xu3Dbaj64ZPmHbkHpfD"><p>A mysterious little compaction animation</p></div><p><span id="source-block-20rTLlKbnexxe40S0vzFpN"></span></p><h4 id="fast-track-for-small-graphs" tabindex="-1">Fast Track for Small Graphs <a class="header-anchor" href="#fast-track-for-small-graphs" aria-label="Permalink to &quot;Fast Track for Small Graphs&quot;">​</a></h4><p>Small graphs usually do not require complicated heuristics; a finite set of placements can be tried directly.</p><p>Search retains three types of exact branch:</p><p>These supplement the main search under the principle “enumerate when you can, rather than guess.” Heuristic search has limits. Recognizing problem size and switching to a more exact method when appropriate is itself part of the design.</p><p>Why not give every graph to a global MILP/CP-SAT model? The variable count grows rapidly with the grid, edge count and route lengths. Full flow semantics also include simulator cycles and n-to-n behavior, which are difficult to express directly as static constraints.</p><p><span id="source-block-1gGVSlUEoo7ElcC7ACHYzk"></span></p><h4 id="flow-validation" tabindex="-1">Flow Validation <a class="header-anchor" href="#flow-validation" aria-label="Permalink to &quot;Flow Validation&quot;">​</a></h4><p>Once a candidate layout is generated, its flow must be validated under the game&#39;s semantics.</p><p>The gate checks in a fixed order:</p><p>Any failed step, timeout or oracle error returns unknown; it never falls back to valid.</p><p>The gate is more than an implementation detail. It determines how bold search can be: search may use heuristics, but a published result must be provable. Without this gate, all the preceding heuristics might put invalid layouts in front of users. With it, search can freely try and fail.</p><p><span id="source-block-8m9XxLJ9ioxJXOtmlTj0S0"></span></p><h3 id="unresolved-problems" tabindex="-1">Unresolved Problems <a class="header-anchor" href="#unresolved-problems" aria-label="Permalink to &quot;Unresolved Problems&quot;">​</a></h3><ul><li><p>Feedback does not improve every case: on some graphs it delays the first solution or even lowers the first-solution success rate. The current defaults came from screening, not a theorem.</p></li><li><p>Multi-worker results are not bit-for-bit reproducible: completion order changes which tasks get in before the deadline.</p></li><li><p>Continuous compaction depends on Node and browser prototype scripts; without them it can only retain the incumbent.</p></li><li><p>Exact branches cover only very small graphs; larger graphs still rely on heuristics.</p></li><li><p>Splitting topology rewrites add nodes and may improve layout feasibility while worsening the second objective. Experiments must still establish when they are worthwhile.</p></li><li><p>The “intuition” in reference layouts has not been fully formalized. Corridors, ports, contact chains and return paths matter, but their weights are still determined by search ranking and experimental tuning.</p></li></ul><p><span id="source-block-odVp5F1OTsOVcgPtSBlzUx"></span></p><h3 id="smaller-and-more-stable-with-some-results" tabindex="-1">Smaller and More Stable, with Some Results <a class="header-anchor" href="#smaller-and-more-stable-with-some-results" aria-label="Permalink to &quot;Smaller and More Stable, with Some Results&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4a3becc542521e50.q90-612c947bbbf40814.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="g0fDVZsErGshPjVRdRjFJz"><p>Beating the manual-layout team! (Though I feel the manual team didn&#39;t really try to compact it 😡😡😡)</p></div><p>The current solver is well suited to producing excellent layouts quickly. It does not guarantee that solutions keep improving toward optimality over longer runs, and it cannot enumerate the solution space.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b89be2470af17b79.q90-b42819225be4b1b1.webp" alt="Compression Algorithms for Idealized Systems"></p><div class="logistics-image-caption" data-source-block="tYu5H8y2k4IHVQIkTv4syf"><p>Still, we actually don&#39;t know whether there is a solution better than 88.</p></div><p>A better approach is to use this algorithm to generate a prototype layout quickly, then optimize it with a general-purpose exhaustive algorithm.</p><p>Also, I want endless CPU cores 😭😭😭😭😭 Give me CPUs 😭😭😭😭😭 I want an HPC cluster 😭😭😭😭😭😭😭😭 GPUs too 😭😭😋😭😭😭 Such a computing-power shortage 😭😭😭😭😭 Please, give me some, I&#39;ll do anything 😭😭😭😭</p></div>',1)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
